## Duplicate Prevention Strategy

### Backend WindowRegistry
```rust
pub struct WindowRegistry {
    // session_id -> window_label mapping
    session_windows: Arc<RwLock<HashMap<String, String>>>,
}

impl WindowRegistry {
    fn has_window(&self, session_id: &str) -> bool {
        self.session_windows.read().unwrap()
            .contains_key(session_id)
    }

    fn register_window(&self, session_id: String, label: String) {
        self.session_windows.write().unwrap()
            .insert(session_id, label);
    }

    fn unregister_window(&self, session_id: &str) {
        self.session_windows.write().unwrap()
            .remove(session_id);
    }
}

#[tauri::command]
async fn create_session_window(
    app: AppHandle,
    registry: State<WindowRegistry>,
    session_id: String,
) -> Result<String, String> {
    // Check if window already exists
    if registry.has_window(&session_id) {
        return Err(format!(
            "Window already open for session {}", 
            session_id
        ));
    }

    // Create window...
    registry.register_window(session_id.clone(), label);
    Ok(label)
}
```

