- Single event listener for session-list-changed
- Initial poll with listActiveSessions()

Example structure:
```typescript
import { create } from 'zustand';
import { SessionInfo, listActiveSessions, onSessionListChanged } from '../api';

interface SessionStore {
  sessions: SessionInfo[];
  sessionsByBead: Record<string, SessionInfo[]>;
  init: () => void;
}

export const useSessionStore = create<SessionStore>((set, get) => ({
  sessions: [],
  sessionsByBead: {},

  init: () => {
    // Load initial sessions
    listActiveSessions().then(sessions => {
      set({ 
        sessions,
        sessionsByBead: groupByBead(sessions)
      });
    });

    // Subscribe to updates
    onSessionListChanged((sessions) => {
      set({ 
        sessions,
        sessionsByBead: groupByBead(sessions)
      });
    });
  }
}));

function groupByBead(sessions: SessionInfo[]): Record<string, SessionInfo[]> {
  const grouped: Record<string, SessionInfo[]> = {};
  sessions.forEach(s => {
    const key = s.beadId || 'untracked';
    if (\!grouped[key]) grouped[key] = [];
    grouped[key].push(s);
  });
  return grouped;
}
```

