## Drag Logic
```typescript
const [panelWidth, setPanelWidth] = useState(300);
const MIN_WIDTH = 200;
const MAX_WIDTH = 600;

const handleMouseDown = (e: React.MouseEvent) => {
  const startX = e.clientX;
  const startWidth = panelWidth;

  const handleMouseMove = (e: MouseEvent) => {
    const delta = e.clientX - startX;
    const newWidth = Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, startWidth + delta));
    setPanelWidth(newWidth);
  };

  const handleMouseUp = () => {
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
    // Save to startup.json (debounced)
  };

  document.addEventListener('mousemove', handleMouseMove);
  document.addEventListener('mouseup', handleMouseUp);
};
```

## Constraints
- Min width: 200px
- Max width: 600px
- Smooth updates (no lag)

## Integration with Startup State
- Add to startup.json: `ui.wbsPanelWidth`
- Debounced save on resize (500ms)
- Load on app startup before render

## Save Logic
```typescript
// Debounced save after drag ends
const debouncedSave = useCallback(
  debounce((width: number) => {
    saveStartupState({ ui: { wbsPanelWidth: width } });
  }, 500),
  []
);

// On resize
useEffect(() => {
  debouncedSave(panelWidth);
}, [panelWidth]);
```

## Load Logic
