  loadStartupState().then(state => {
    if (state?.ui?.wbsPanelWidth) {
      setPanelWidth(state.ui.wbsPanelWidth);
    }
  });
}, []);
```

## Drag State
```typescript
const [position, setPosition] = useState({ x: 100, y: 100 });
const [isDragging, setIsDragging] = useState(false);
const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
```

## Event Handlers
```typescript
const handleMouseDown = (e: React.MouseEvent) => {
  setIsDragging(true);
  setDragOffset({
    x: e.clientX - position.x,
    y: e.clientY - position.y
  });
};

const handleMouseMove = (e: MouseEvent) => {
  if (!isDragging) return;

  const newX = Math.max(0, Math.min(e.clientX - dragOffset.x, window.innerWidth - 800));
  const newY = Math.max(0, Math.min(e.clientY - dragOffset.y, window.innerHeight - 600));

  setPosition({ x: newX, y: newY });
};

const handleMouseUp = () => {
  setIsDragging(false);
};
```

## useEffect for Listeners
```typescript
useEffect(() => {
  if (isDragging) {
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  }
  return () => {
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
  };
}, [isDragging, dragOffset]);
```

**Root Cause:**
The fitAddon.fit() calculation happens immediately after terminal.open(), but:
1. Font metrics may not be fully loaded yet
2. Container might not be at final rendered size
3. Timing issue between DOM render and dimension calculation

**Proposed Fix:**
Wait for fonts to load before calculating dimensions:

```typescript
// In Terminal.tsx after line 193
terminal.open(terminalRef.current);
fitAddon.fit();

// Wait for fonts to be fully loaded before final fit
document.fonts.ready.then(() => {
  fitAddon.fit();
  const dimensions = fitAddon.proposeDimensions();
  if (dimensions) {
    invoke('resize_pty', {
      sessionId,
      cols: dimensions.cols,
      rows: dimensions.rows,
    });
  }
});
```

**Alternative:** Add requestAnimationFrame to ensure DOM is fully rendered:
```typescript
requestAnimationFrame(() => {
  fitAddon.fit();
  // Send dimensions
});
```

